//! Generated files: `docs/COMMANDS.md` and the skill text.

use crate::root;
use deft_cli::help;
use deft_core::spec::Op;
use deft_ops::registry::registry;
use std::fmt::Write as _;

pub fn write(check: bool) -> Result<(), String> {
    let outputs = [
        ("docs/COMMANDS.md", reference()),
        ("skills/deft/SKILL.md", deft_cli::top::skill_text()),
    ];
    for (path, text) in outputs {
        let file = root().join(path);
        if check {
            if std::fs::read_to_string(&file).ok().as_deref() != Some(text.as_str()) {
                return Err(format!("{path} is out of date; run: cargo xtask site"));
            }
            continue;
        }
        if let Some(dir) = file.parent() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
        std::fs::write(&file, text).map_err(|e| e.to_string())?;
        println!("wrote {path}");
    }
    Ok(())
}

/// What a command needs beyond the binary, as short words.
fn needs(op: &Op) -> Vec<String> {
    op.engines.iter().map(|e| e.to_string()).collect()
}

fn cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

/// `docs/COMMANDS.md`.
fn reference() -> String {
    let reg = registry();
    let mut s = String::from(
        "# Command reference\n\nGenerated by `cargo xtask site` from the command registry. Do not edit this file; change the operation in `crates/deft-ops/src/ops/`. For options, run `deft <group> <command> --help`.\n\nA command marked ffmpeg needs that program installed. See [INSTALL.md](INSTALL.md).\n\n## Any file\n\n| Command | What it does | Example |\n|---|---|---|\n",
    );
    for c in help::TOP_COMMANDS {
        let _ = writeln!(
            s,
            "| `deft {}` | {} | `{}` |",
            c.name,
            cell(c.summary),
            cell(c.example)
        );
    }
    for g in &reg.groups {
        let _ = write!(
            s,
            "\n## {}\n\n{}\n\n| Command | What it does | Needs | Example |\n|---|---|---|---|\n",
            g.name, g.summary
        );
        for (command, op) in reg.commands(g.name) {
            let example = op
                .examples
                .first()
                .map(|e| format!("`{}`", cell(e)))
                .unwrap_or_default();
            let _ = writeln!(
                s,
                "| `deft {} {command}` | {} | {} | {example} |",
                g.name,
                cell(op.summary),
                needs(op).join(", "),
            );
        }
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_command_reaches_the_reference() {
        let doc = reference();
        for g in &registry().groups {
            for (command, _) in registry().commands(g.name) {
                assert!(doc.contains(&format!("`deft {} {command}`", g.name)));
            }
        }
    }

    /// A `: ` in an unquoted YAML value is a syntax error, and the description
    /// has one, so skill loaders would reject the file.
    #[test]
    fn the_skill_description_is_quoted() {
        let text = deft_cli::top::skill_text();
        let line = text.lines().find(|l| l.starts_with("description: "));
        let value = line.unwrap().trim_start_matches("description: ");
        assert!(value.starts_with('"') && value.ends_with('"'), "{value}");
    }
}
